"""Writes versions/1/obligations.toml from the table below (keeps TOML quoting right).  python oracle/make_obligations.py"""
import json
from pathlib import Path

HEAD = Path(__file__).resolve().parent.parent / "versions/1/obligations.toml"
old = HEAD.read_text()
header = old[: old.index("[[obligation]]")] if "[[obligation]]" in old else old
q = json.dumps


def ex(c, *n):
    return [f"{c}#example:{i}" for i in n]


def t(c, *names):
    return [f"{c}#test_{n}" for n in names]


O = []


def ob(id, statement, checks=None, status="decided", kind="behaviour", reason=None, assumes=None, unchecked=None):
    O.append(dict(id=id, statement=statement, checks=checks or [], status=status, kind=kind, reason=reason, assumes=assumes, unchecked=unchecked))


# ---- product-wide
ob("product.no-advice", "The app never gives medical, dose or diagnosis advice: no amount, no 'give', no illness named, no treatment. It shows reminders (the fixed rules of the reminders component), and when a medicine's minimum gap has passed. Every AI prompt carries the same rule, and an AI answer is only ever sorted into entries or a handover the parent reads. Schedules (vaccinations, checkups, dental) only remind of the published recommendation and say that the pediatrician decides; the app never signs in to a calendar.",
   kind="constraint", reason="The product is a log and a reminder, not a medical device; the parents' doctor decides.", unchecked="A review of every screen text, reminder and AI prompt (a list of all prompt texts and all reminder texts) for dose, diagnosis or treatment wording; each prompt states the rule.")
# ---- merge
ob("merge.newest-wins", "Logs merge item by item, matched by id: an item of the other copy replaces the local one only if its updatedAt is strictly greater (missing counts as 0); on a tie the local item stays. Items are never combined field by field.", ex("merge", 2, 3, 4, 8) + t("merge", "the_newer_item_wins_and_a_tie_keeps_local"), assumes=["K-device-clocks", "K-ids-unique"])
ob("merge.tombstones", "A deletion is an item that stays with deleted true and a newer updatedAt, and is merged like any edit: a newer deletion wins, a later edit brings the item back, an older deletion loses.", ex("merge", 5, 6, 7) + t("merge", "a_deletion_is_never_forgotten_by_a_merge"))
ob("merge.order", "The merged list keeps the local items in their order (a replaced item keeps its place), then appends the other copy's new items in their order; merging the same copy again changes nothing.", ex("merge", 1, 2) + t("merge", "order_is_local_first_then_new_items_of_incoming", "merging_again_changes_nothing"))
ob("merge.collections", "All 14 synced collections (children, episodes, entries, meds, measurements, growth, products, vaccines, checkups, dental, appts, emergency, docs, pages) merge this way; a collection the other copy lacks is left alone. Anything new that syncs must be added to this list.", ex("merge", 9))
ob("merge.example-data", "A log that only holds example data is replaced by an empty log (settings kept) before merging, so example items never mix with real ones.", ex("merge", 10))
ob("merge.selected-child", "After a merge the selected child stays; without one, the first child that is not deleted is selected, else none.", ex("merge", 11, 12))
ob("merge.accept", "Only Aura logs are merged in (app 'aura' or the old 'sick-day-log'); a log of a newer format version is refused with a message to update, and an older one is first brought up to the current format.", ex("merge", 13, 14, 15, 16, 17))
ob("merge.foreign-file", "A Drive file counts as an Aura log only if app is 'aura' or 'sick-day-log' and entries is a list; the app never writes over anything else.", ex("merge", 24, 25, 26, 27, 28), kind="security")
ob("merge.covered", "After writing, the app checks that nothing of the phone's was lost to another phone's write: every item of the phone must be in the remote copy with at least its updatedAt.", ex("merge", 18, 19, 20, 21) + t("merge", "covered_means_every_item_is_there_and_as_new"))
ob("merge.unknown-parts", "Top-level parts of the Drive file that this version does not know (added by a later version) are written back unchanged; known keys are app, v, savedAt, example, settings, child, drive, recalls, docTr and the 14 collections.", ex("merge", 22, 23))
