out = [header.rstrip() + "\n"]
for o in O:
    s = [f"[[obligation]]", f"id = {q(o['id'])}", f"statement = {q(o['statement'], ensure_ascii=False)}", f"status = {q(o['status'])}", 'source = "extract"', f"kind = {q(o['kind'])}"]
    if o["reason"]:
        s.append(f"reason = {q(o['reason'], ensure_ascii=False)}")
    if o["assumes"]:
        s.append(f"assumes = {q(o['assumes'])}")
    s.append(f"checks = {q(o['checks'])}")
    if o["unchecked"]:
        s.append(f"unchecked = {q(o['unchecked'], ensure_ascii=False)}")
    out.append("\n".join(s) + "\n")
HEAD.write_text("\n".join(out))
print(len(O), "obligations,", sum(1 for o in O if o["unchecked"]), "unchecked")
